custom_css:
@import url('/css/tavernnext-atelier.css');
@import url('/css/tavernnext-mineral.css');

:root {
    --tn-accent: #176b72;
    --tn-accent-hover: #0f5960;
    --tn-accent-soft: rgba(23, 107, 114, 0.14);
    --tn-accent-fill: #c9e3df;
    --tn-accent-fill-hover: #b7d7d1;
    --tn-accent-contrast: #0d2e31;
    --tn-accent-border: #8fc2ba;
    --tn-accent-highlight: rgba(255, 255, 255, 0.74);
    --tn-accent-shadow: rgba(23, 107, 114, 0.18);
    --tn-warm: #9b6633;
    --tn-status-contrast: #ffffff;
    --tn-surface-0: rgba(243, 245, 242, 0.98);
    --tn-surface-1: rgba(252, 253, 250, 0.98);
    --tn-surface-2: rgba(233, 238, 235, 0.98);
    --tn-surface-solid: #ffffff;
    --tn-field: rgba(241, 244, 242, 0.98);
    --tn-field-hover: #ffffff;
    --tn-field-highlight: rgba(255, 255, 255, 0.9);
    --tn-hover: rgba(23, 107, 114, 0.1);
    --tn-active: rgba(23, 107, 114, 0.17);
    --tn-selected: rgba(23, 107, 114, 0.13);
    --tn-hairline: rgba(39, 58, 52, 0.14);
    --tn-code-bg: #e7ecea;
    --tn-code-text: #273637;
    --tn-danger: #a23849;
    --tn-success: #3b7661;
    --tn-warning: #94662d;
    --tn-scrollbar: rgba(78, 103, 95, 0.36);
    --tn-shadow-sm: 0 1px 2px rgba(22, 32, 28, 0.05), 0 5px 18px rgba(22, 32, 28, 0.07);
    --tn-shadow-lg: 0 14px 36px rgba(22, 32, 28, 0.14);
}

body { color-scheme: light !important; }
